1560	{
1561		u32 inta;
1562	
1563		lockdep_assert_held(&IWL_TRANS_GET_PCIE_TRANS(trans)->irq_lock);
1564	
1565		trace_iwlwifi_dev_irq(trans->dev);
1566	
1567		/* Discover which interrupts are active/pending */
